['Light/Clean','Dark/Clean'].forEach(function(a){var p=H.page('Proto macOS '+a.split('/')[0]);['customize','customize--profile','artifacts--detail'].forEach(function(id){var s=p.layers.find(function(l){return l.name==='Screen/macos/'+a+'/'+id});if(!s)return;sketch.find('SymbolInstance',s).forEach(function(i){if(i.name==='artifact-panel')i.name='link:artifacts--detail';if(i.name==='link:customize')i.overrides.filter(function(o){return o.property==='stringValue'}).forEach(function(o){o.value='Enabled';});});H.out({app:a,id:id,refined:true});});});